def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= 120:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                b = float(prev.get('bid', 0.0))
            except Exception:
                b = 0.0
            if b >= 0:
                prev_bids.append(b)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 0.55
    elif hp <= 4:
        danger += 0.3
    if no_water_days >= 1:
        danger += 0.25
    if no_water_days >= 2:
        danger += 0.2

    pressure = 0.0
    if highest_prev >= 130:
        pressure = 0.9
    elif highest_prev >= 100:
        pressure = 0.72
    elif highest_prev >= 70:
        pressure = 0.55
    elif highest_prev >= 35:
        pressure = 0.35
    else:
        pressure = 0.18

    pressure += 0.08 * urgent_opp
    pressure += 0.03 * rich_opp
    pressure += 0.18 * scarcity

    target_frac = 0.18 + 0.42 * pressure + danger

    if supply >= 22:
        target_frac -= 0.1
    elif supply <= 17:
        target_frac += 0.12

    if day >= 8:
        target_frac += 0.08

    if hp >= 8 and budget < 140:
        target_frac -= 0.08

    if target_frac < 0.12:
        target_frac = 0.12
    if target_frac > 0.98:
        target_frac = 0.98

    bid = DAILY_SALARY * target_frac

    if highest_prev > 0:
        if hp <= 4 or no_water_days >= 1 or supply <= 17:
            bid = max(bid, min(highest_prev + 3.0, DAILY_SALARY * 1.35))
        elif supply >= 22 and hp >= 7:
            bid = min(bid, avg_prev * 0.75 + 2.0)

    if hp <= 2:
        bid = max(bid, 78.0)
    if no_water_days >= 2:
        bid = max(bid, 90.0)

    if budget < bid:
        bid = budget

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Basic safety
    if my_status['budget'] <= 0:
        return 0

    # Alive opponents and yesterday bids
    alive_opponents = []
    yesterday_bids = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if isinstance(prev, dict):
                b = prev.get('bid', None)
                if b is not None:
                    yesterday_bids.append(float(b))

    # If no info, conservative
    if not alive_opponents:
        return min(my_status['budget'], int(DAILY_SALARY * 0.5))

    # Use Cindy/Alex pressure from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units we can buy with our budget (rough)
    # Not exact game mechanics, but helps scale aggression.
    budget = float(my_status['budget'])
    hp = float(my_status['hp'])

    # Supply pressure: medium scenario suggests supply is near mid; bid slightly above typical
    # Normalize supply to [0,1]
    s_norm = (float(supply) - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    if s_norm < 0:
        s_norm = 0.0
    if s_norm > 1:
        s_norm = 1.0

    # Base aggression factor
    # If Cindy was near the top, we need to overtake; else we can undercut.
    # Use a threshold tied to yesterday's best.
    # Target: win enough water to preserve HP; if HP low, bid more.
    if highest_prev_bid >= DAILY_SALARY * 1.35:
        # Cindy-like aggressive day
        if hp <= 2:
            target = DAILY_SALARY * (0.95 + 0.15 * s_norm)
        elif hp <= 4:
            target = DAILY_SALARY * (0.75 + 0.10 * s_norm)
        else:
            target = DAILY_SALARY * (0.65 + 0.10 * s_norm)
    elif highest_prev_bid >= DAILY_SALARY * 0.95:
        # Moderate pressure
        if hp <= 2:
            target = DAILY_SALARY * (0.85 + 0.10 * s_norm)
        else:
            target = DAILY_SALARY * (0.55 + 0.10 * s_norm)
    else:
        # Low pressure: bid just enough
        if hp <= 2:
            target = DAILY_SALARY * (0.75 + 0.10 * s_norm)
        else:
            target = DAILY_SALARY * (0.45 + 0.08 * s_norm)

    # Small bump to beat the previous highest bid when near win-critical
    # (We don't know today's bids, so use a gentle +1.5 rather than jumping to max.)
    target = float(target)
    if highest_prev_bid > 0:
        target = max(target, highest_prev_bid + 1.5)

    # If our budget is low relative to target, scale down
    if budget < target:
        target = budget * 0.95

    # Ensure integer and non-negative
    bid = int(target)
    if bid < 0:
        bid = 0

    # Never bid more than budget
    if bid > int(budget):
        bid = int(budget)

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    total_opponent_water_req = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
        total_opponent_water_req += opp['water_requirement']

    # Determine supply context
    can_i_get_my_water = day_context['supply'] >= WATER_REQ
    is_supply_abundant_for_all = day_context['supply'] >= (WATER_REQ + total_opponent_water_req)

    bid_amount = 0.0

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # High pressure scenario: Opponents bid very high yesterday
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3 and is_supply_abundant_for_all:
                # Can afford to lose HP and supply is abundant, try to conserve
                bid_amount = DAILY_SALARY * 0.3
            else:
                # Critical HP OR supply is scarce, must bid high
                bid_amount = DAILY_SALARY * 0.95
        else:
            # Moderate pressure scenario: Opponents' highest bid was not super high
            # Adjust bid based on supply abundance
            if is_supply_abundant_for_all:
                # Supply is abundant for everyone, can try to get it cheaper
                bid_amount = max(DAILY_SALARY * 0.4, highest_prev_bid + 1.0)
            elif can_i_get_my_water:
                # Supply is competitive but I can still get my water, bid slightly above highest previous bid
                bid_amount = max(DAILY_SALARY * 0.6, highest_prev_bid + 2.0)
            else: # I cannot get my water (supply < WATER_REQ)
                if my_status['hp'] <= 1:
                    # Extremely desperate, bid high just in case of edge allocation rules
                    bid_amount = DAILY_SALARY * 0.95
                else:
                    # Conserve budget, no point bidding high if I can't get water
                    bid_amount = 1.0

    else: # No yesterday's bids available (e.g., first day, or all opponents were inactive)
        if my_status['hp'] <= 2: # Critical HP
            bid_amount = DAILY_SALARY * 0.9
        elif my_status['no_water_days'] > 0: # Missed water yesterday
            bid_amount = DAILY_SALARY * 0.8
        elif is_supply_abundant_for_all:
            # Abundant supply, no history, bid conservatively
            bid_amount = DAILY_SALARY * 0.4
        elif can_i_get_my_water:
            # Competitive supply, no history, bid moderately
            bid_amount = DAILY_SALARY * 0.6
        else: # I cannot get my water
            if my_status['hp'] <= 1:
                bid_amount = DAILY_SALARY * 0.9
            else:
                bid_amount = 1.0

    # Ensure bid does not exceed budget and is at least 1.0
    final_bid = min(my_status['budget'], bid_amount)
    if num_alive_opponents > 0 and final_bid < 5.0 and can_i_get_my_water: 
        # Ensure a reasonable minimum bid if water is possible and competition exists
        final_bid = 5.0
    return max(1.0, final_bid)
